      "class": "ru.child",
      "verdict": "supported",
      "reason": "A child pedestrian is a person rather than a vehicle, so none of the admitting limbs reaches the class."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "The general vehicle limb admits this class subject to the stated occupancy condition, without requiring commercial status."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "Electric bicycles are expressly excepted from the nested vehicle definition and are not restored by another admitting limb."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "Electric scooters are expressly excepted from the nested vehicle definition and are not restored by another admitting limb."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "The general vehicle limb admits this class subject to the occupancy condition, without making emergency designation or responding conduct sufficient by itself."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "supported",
      "reason": "A fire-fighting vehicle falls within the general vehicle admission subject to the stated occupancy condition."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "Mopeds fall within the general vehicle admission subject to occupancy, even though the motorcycle definition excludes them from that separate limb."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "The general vehicle limb admits this self-propelled vehicle class subject to the stated occupancy condition."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The definition expressly admits motorcycles regardless of the number of passengers."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "The general vehicle limb admits this vehicle class subject to the occupancy condition, without making official service sufficient by itself."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes persons rather than vehicles, and the nested definition additionally excludes electric personal assistive mobility devices."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The class consists of pedestrians rather than vehicles, so none of the admitting limbs reaches it."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The nested vehicle definition expressly excepts devices used exclusively upon stationary rails."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "The general vehicle admission reaches this class subject to occupancy, while the bus limb independently admits buses meeting the posted bus definition regardless of passenger count."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "Taxicabs fall within the general vehicle admission subject to occupancy, notwithstanding their exclusion from the separate bus definition."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "supported",
      "reason": "Both alternatives in the class contract are vehicles reached by the general admitting limb subject to the stated occupancy condition."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "supported",
      "reason": "The nested vehicle definition expressly reaches devices used for transport or drawing, and the admitting limb retains its occupancy condition."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "The general vehicle admission reaches this class subject to occupancy, while the bus limb independently admits buses meeting the posted bus definition regardless of passenger count."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "The general vehicle limb admits goods-carrying motor vehicles subject to the stated occupancy condition."
    }
  ]
}

